      cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemBytes));
  probe<<<kGrid, 384, kSmemBytes>>>(q, k, v, rounds, mode, output);
  CHECK(cudaGetLastError());
  CHECK(cudaDeviceSynchronize());
  std::vector<float> sums(kGrid * 2);
  CHECK(cudaMemcpy(sums.data(), output, sums.size() * sizeof(float),
                   cudaMemcpyDeviceToHost));
  double checksum = 0;
  for (float value : sums) {
    if (!std::isfinite(value)) return 3;
    checksum += value;
  }
  std::printf("{\"rounds\":%d,\"barrier_mode\":%d,\"checksum\":%.12g}\n",
              rounds, mode, checksum);
  CHECK(cudaFree(output));
  CHECK(cudaFree(source));
  return 0;
}
